import sys

import pgzrun

mod = sys.modules['__main__']

WIDTH = 700
HEIGHT = 700

colors = ["blue", "red", "purple", "green", "orange", "yellow"]
index = 0
box = mod.Actor(colors[index], (350, 350))
box_grab = False


def draw():
    box.draw()


def on_mouse_up():
    global box_grab
    box_grab = False


def on_mouse_down(pos, button):
    global box_grab
    if box.collidepoint(pos) and button == mod.mouse.LEFT:
        box_grab = True


def on_mouse_move(pos):
    if box_grab:
        x, y = pos
        box.x = x
        box.y = y


def on_key_down(key):
    global index
    if key == mod.keys.SPACE:
        mod.screen.clear()
    if key == mod.keys.A:
        index -= 1
        if index < 0:
            index = 5
    if key == mod.keys.D:
        index = (index + 1) % 6

    box.image = colors[index]


