import random
import sys

import pgzrun

mod = sys.modules['__main__']

WIDTH = 500
HEIGHT = 400

# rocket
rocket = mod.Actor('rocket', (200, 360))

# rocks
rock1 = mod.Actor('rocks', (300, 0))
rock2 = mod.Actor('rocks2', (100, -2))
rock3 = mod.Actor('rocks3', (200, -10))
rocks = [rock1, rock2, rock3]

# lives
lives = 3


def draw():
    mod.screen.clear()

    if lives > 0:
        rocket.draw()
        for rock in rocks:
            rock.draw()
        mod.screen.draw.text(
            "Lives: ", center=(35, 25), fontsize=30, color=(255, 255, 255)
        )
        mod.screen.draw.text(
            str(lives), center=(40, 55), fontsize=30, color=(255, 255, 255)
        )
    else:
        mod.screen.draw.text(
            "GAME OVER", center=(250, 200), fontsize=100, color=(255, 255, 255)
        )


def checkCollision():
    for rock in rocks:
        if rocket.colliderect(rock):
            resetRock(rock)
            return True
    return False


def moveRocket():
    rocket.image = 'rocket'

    if mod.keyboard.left:
        rocket.image = 'rocket-left'
        if rocket.x > 40:
            rocket.x -= 7

    if mod.keyboard.right:
        rocket.image = 'rocket-right'
        if rocket.x < 460:
            rocket.x += 7


def moveRocks():
    for i, rock in enumerate(rocks):
        rock.y += 5 + i
        rock.angle += 1
        if rock.y > HEIGHT:
            resetRock(rock)


def resetRock(rock):
    rock.x = random.randint(50, WIDTH - 50)
    rock.y = 0


def update():
    global lives

    if checkCollision():
        lives -= 1

    moveRocket()
    moveRocks()


pgzrun.go()

PyG7-Beach-Ball-Dodge.py.content:
import sys

import pgzrun

mod = sys.modules['__main__']

WIDTH = 500
HEIGHT = 700

bRect = mod.Rect((WIDTH / 2, 670), (20, 20))
rects = []
timer = 0
for i in range(6):
    r = mod.Actor("beach_ball", (WIDTH / 2, i * 110 + 75))
    if i % 2 == 0:
        r.xspeed = -5
    else:
        r.xspeed = 5
    rects.append(r)

gameState = "start"


def draw():
    mod.screen.clear()

    if gameState == "play":
        mod.screen.draw.filled_rect(bRect, (10, 10, 255))
        mod.screen.draw.text(
            "Timer: " + str(timer),
            center=(50, 30),
            fontsize=30,
            color=(255, 255, 255),
        )

        for rect in rects:
            rect.draw()
    elif gameState == "start":
        mod.screen.draw.text(
            "Avoid the beach balls!\nPress space to begin!",
            center=(WIDTH / 2, HEIGHT / 2),
            fontsize=50,
            color=(255, 255, 255),
        )
    else:
        mod.screen.draw.text(
            "You lasted "
            + str(timer)
            + " seconds!\n Press space to play again!",
            center=(WIDTH / 2, HEIGHT / 2),
            fontsize=50,
            color=(255, 255, 255),
        )


# commands triggered at the start of the game
def startGame():
    mod.clock.schedule_interval(increaseSize, 5.0)
    mod.clock.schedule_interval(increaseTimer, 1.0)


def endGame():
    mod.clock.unschedule(increaseSize)
    mod.clock.unschedule(increaseTimer)


def increaseSize():
    bRect.inflate_ip(10, 10)


def increaseTimer():
    global timer
    timer += 1


def moveSquare():
    if mod.keyboard.up and bRect.top > 0:
        bRect.y -= 10

    if mod.keyboard.down and bRect.bottom < HEIGHT:
        bRect.y += 10

    if mod.keyboard.left and bRect.left > 0:
        bRect.x -= 10

    if mod.keyboard.right and bRect.right < WIDTH:
        bRect.x += 10


def update():
    global gameState, bRect, timer

    if gameState == "play":
        moveSquare()

        for rect in rects:
            if rect.colliderect(bRect):
                gameState = "end"
                endGame()
                break

            if rect.left < 0 or rect.right > WIDTH:
                rect.xspeed = -rect.xspeed

            rect.x += rect.xspeed

    else:
        if mod.keyboard.space:
            gameState = "play"
            timer = 0
            bRect = mod.Rect((WIDTH / 2, 670), (20, 20))
            startGame()

        if mod.keyboard.escape:
            quit()


pgzrun.go()

PyG8-Asteroid-Shoot.py.content:
import random
import sys

import pgzrun

mod = sys.modules['__main__']

WIDTH = 500
HEIGHT = 500

ship = mod.Actor("spaceship", (WIDTH / 2, HEIGHT - 50))
projectiles = []

# rocks
rock1 = mod.Actor('rocks', (300, 0))
rock2 = mod.Actor('rocks2', (100, -50))
rock3 = mod.Actor('rocks3', (200, -100))
rocks = [rock1, rock2, rock3]
for rock in rocks:
    rock.yspeed = 3

gameState = "start"

timer = 0


def draw():
    mod.screen.clear()

    if gameState == "play":
        ship.draw()
        mod.screen.draw.text(
            "Timer: " + str(timer),
            center=(50, 25),
            fontsize=30,
            color=(255, 255, 255),
        )
        for rock in rocks:
            rock.draw()
        for projectile in projectiles:
            mod.screen.draw.filled_rect(projectile, (255, 255, 255))

    elif gameState == "start":
        mod.screen.draw.text(
            "Press Enter to Start the Game!",
            center=(WIDTH / 2, HEIGHT / 2),
            fontsize=40,
            color=(255, 255, 255),
        )
    else:
        mod.screen.draw.text(
            "You lasted " + str(timer) + " seconds!",
            center=(WIDTH / 2, HEIGHT / 2 - 80),
            fontsize=40,
            color=(255, 255, 255),
        )
        mod.screen.draw.text(
            "Game Over!\nPress Enter to Play Again \nor Escape to Quit!",
            center=(WIDTH / 2, HEIGHT / 2),
            fontsize=40,
            color=(255, 255, 255),
        )


def on_key_down(key):
    global fired, projectiles
    if key == mod.keys.SPACE:
        rock = mod.Rect((ship.x, ship.y - 50), (10, 10))
        projectiles.append(rock)


def increaseTimer():
    global timer
    timer += 1


def moveShip():
    if mod.keyboard.left and ship.left > 0:
        ship.x -= 10

    if mod.keyboard.right and ship.right < WIDTH:
        ship.x += 10


def moveRocks():
    global gameState
    for rock in rocks:
        rock.y += rock.yspeed
        rock.angle += 1

        if rock.y > HEIGHT or rock.colliderect(ship):
            gameState = "end"

            for rock2 in rocks:
                resetRockPosition(rock2)

            resetRocks()
            mod.clock.unschedule(increaseTimer)
            mod.clock.unschedule(increaseSpeed)


def increaseSpeed():
    for rock in rocks:
        rock.yspeed += 1


def resetRockPosition(rock):
    rock.x = random.randint(50, WIDTH - 50)
    rock.y = 0


def resetRocks():
    for rock in rocks:
        rock.yspeed = 3


def update():
    global fired, projectiles, gameState, timer

    if gameState == "start" or gameState == "end":
        if mod.keyboard.RETURN or mod.keyboard.kp_enter:
            gameState = "play"
            timer = 0
            mod.clock.schedule_interval(increaseTimer, 1.0)
            mod.clock.schedule_interval(increaseSpeed, 5.0)

        if mod.keyboard.escape:
            quit()

    else:
        moveShip()
        moveRocks()

        for projectile in projectiles:
            projectile.y -= 10

            if projectile.y <= 0:
                projectiles.remove(projectile)

            for rock in rocks:
                if rock.colliderect(projectile):
                    if projectile in projectiles:
                        projectiles.remove(projectile)
                    resetRockPosition(rock)


pgzrun.go()
